package com.example.demo;

import java.net.URI;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/greetings")
public class GreetingController {
    public record GreetingRequest(String name) {}
    public record GreetingResponse(long id, String message) {}

    private final Map<Long, GreetingResponse> greetings = new ConcurrentHashMap<>();
    private final AtomicLong ids = new AtomicLong();

    @PostMapping
    public ResponseEntity<GreetingResponse> create(@RequestBody GreetingRequest request) {
        long id = ids.incrementAndGet();
        GreetingResponse greeting = new GreetingResponse(id, "Hello, " + request.name());
        greetings.put(id, greeting);
        return ResponseEntity.created(URI.create("/greetings/" + id)).body(greeting);
    }

    @GetMapping("/{id}")
    public ResponseEntity<GreetingResponse> find(@PathVariable("id") long id) {
        GreetingResponse greeting = greetings.get(id);
        if (greeting == null) {
            return ResponseEntity.notFound().build();
        }
        return ResponseEntity.ok(greeting);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> delete(@PathVariable("id") long id) {
        greetings.remove(id);
        return ResponseEntity.noContent().build();
    }
}

package com.example.demo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class DemoApplication {
    public static void main(String[] args) {
        SpringApplication.run(DemoApplication.class, args);
    }
}
